// Assessment type is chosen on the Type step; show it here without editing it.
const [fixedAssessmentType, setFixedAssessmentType] = useState("MCQ");
useEffect(() => {
  const id = getActiveAssessmentId();
  const chosen = id ? getAssessment(id)?.typeLabel : undefined;
  if (!chosen) return;
  const label = chosen === "Multiple Choice Question (MCQ)" ? "MCQ" : chosen;
  setFixedAssessmentType(label);
  setForm(previous => previous.assessmentType === chosen ? previous : { ...previous, assessmentType: chosen });
}, []);

